{"items":[{"id":"cap-v2-replacement-string_and_unicode-go-repair-01","test_code":"package solution

import (
	"fmt"
	"strings"
	"sync"
	"testing"
	"unicode"
)

func TestCanonicalizeCaptionExamples(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want string
	}{
		{name: "empty", in: "", want: ""},
		{name: "plain text", in: "hello world", want: "hello world"},
		{name: "leading and trailing", in: "  hello world  ", want: "hello world"},
		{name: "mixed ASCII whitespace", in: "\t\n hello\r\v\f world \n", want: "hello world"},
		{name: "all whitespace", in: " \t\r\n\v\f ", want: ""},
		{name: "Unicode text", in: "  नमस्ते\t世界\n🙂  ", want: "नमस्ते 世界 🙂"},
		{name: "combining marks", in: "  e\u0301\tक\u093f  ", want: "e\u0301 क\u093f"},
		{name: "embedded NUL", in: "\x00 \x00", want: "\x00 \x00"},
		{name: "replacement rune", in: " \uFFFD\t\uFFFD ", want: "\uFFFD \uFFFD"},
		{name: "zero width space is preserved", in: " a\u200bb ", want: "a\u200bb"},
		{name: "BOM is preserved", in: "\ufeff x \ufeff", want: "\ufeff x \ufeff"},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if got := CanonicalizeCaption(tc.in); got != tc.want {
				t.Fatalf("CanonicalizeCaption(%q) = %q; want %q", tc.in, got, tc.want)
			}
		})
	}
}

func TestCanonicalizeCaptionRecognizesEveryUnicodeSpace(t *testing.T) {
	var allSpaces strings.Builder
	var separated strings.Builder
	count := 0

	for r := rune(0); r <= unicode.MaxRune; r++ {
		if unicode.IsSpace(r) {
			allSpaces.WriteRune(r)
			if count > 0 {
				separated.WriteRune(r)
			}
			separated.WriteRune('x')
			count++
		}
	}

	if got := CanonicalizeCaption(allSpaces.String()); got != "" {
		t.Fatalf("all Unicode whitespace canonicalized to %q; want empty string", got)
	}

	want := strings.Repeat("x ", count-1) + "x"
	if got := CanonicalizeCaption(separated.String()); got != want {
		t.Fatalf("Unicode whitespace separators produced %q; want %q", got, want)
	}
}

func TestCanonicalizeCaptionPreservesNonWhitespaceRunesExactly(t *testing.T) {
	in := "\u200b\u200c\u200d\ufeff\x00A界🙂e\u0301"
	if got := CanonicalizeCaption(in); got != in {
		t.Fatalf("CanonicalizeCaption(%q) = %q; non-whitespace runes were changed", in, got)
	}
}

func TestCanonicalizeCaptionLongBoundaryRuns(t *testing.T) {
	in := strings.Repeat("\u3000", 4096) + "left" + strings.Repeat("\t\u00a0\n", 4096) + "right" + strings.Repeat("\u2029", 4096)
	if got, want := CanonicalizeCaption(in), "left right"; got != want {
		t.Fatalf("long boundary input produced %q; want %q", got, want)
	}
}

func TestCanonicalizeCaptionCallsAreStateIsolated(t *testing.T) {
	calls := []struct {
		in   string
		want string
	}{
		{in: " first ", want: "first"},
		{in: "", want: ""},
		{in: "\tsecond\nvalue\t", want: "second value"},
		{in: "   ", want: ""},
		{in: "三\u3000四", want: "三 四"},
		{in: "x", want: "x"},
		{in: " first ", want: "first"},
	}

	for i, call := range calls {
		if got := CanonicalizeCaption(call.in); got != call.want {
			t.Fatalf("call %d: CanonicalizeCaption(%q) = %q; want %q", i, call.in, got, call.want)
		}
	}
}

func TestCanonicalizeCaptionConcurrentCallsAreIsolated(t *testing.T) {
	const workers = 32
	const iterations = 50

	start := make(chan struct{})
	errs := make(chan string, workers)
	var wg sync.WaitGroup

	for worker := 0; worker < workers; worker++ {
		worker := worker
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-start

			in := fmt.Sprintf(" \tworker-%d\u3000value\n ", worker)
			want := fmt.Sprintf("worker-%d value", worker)
			for i := 0; i < iterations; i++ {
				if got := CanonicalizeCaption(in); got != want {
					errs <- fmt.Sprintf("worker %d iteration %d: got %q, want %q", worker, i, got, want)
					return
				}
			}
		}()
	}

	close(start)
	wg.Wait()
	close(errs)

	for err := range errs {
		t.Error(err)
	}
}

func TestCanonicalizeCaptionDoesNotMutateInputStorage(t *testing.T) {
	inputBytes := []byte(" \timmutable\u3000text\n ")
	before := append([]byte(nil), inputBytes...)
	input := string(inputBytes)

	if got, want := CanonicalizeCaption(input), "immutable text"; got != want {
		t.Fatalf("CanonicalizeCaption(%q) = %q; want %q", input, got, want)
	}
	if string(inputBytes) != string(before) {
		t.Fatalf("input storage changed from %q to %q", before, inputBytes)
	}
}
"}]}

